"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["2667"],{4474(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>u,frontMatter:()=>i,contentTitle:()=>h,toc:()=>d,assets:()=>l});var s=JSON.parse('{"id":"m7-envoy-ingress/lesson","title":"Lesson: Exposing Services with Ingress & the Gateway API (Envoy)","description":"By now the Fernwood Goods app runs fully on the cluster. You have a frontend Deployment, a backend","source":"@site/docs/m7-envoy-ingress/lesson.md","sourceDirName":"m7-envoy-ingress","slug":"/m7-envoy-ingress/lesson","permalink":"/k8s-distributed-systems/docs/m7-envoy-ingress/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Exposing Services with Ingress & the Gateway API (Envoy)"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/k8s-distributed-systems/docs/m6-storage-statefulsets/deep-dive"},"next":{"title":"Lab: Exposing Services with Ingress & the Gateway API (Envoy)","permalink":"/k8s-distributed-systems/docs/m7-envoy-ingress/lab"}}'),o=t(4848),r=t(8453),a=t(7684);let i={sidebar_position:1,title:"Lesson: Exposing Services with Ingress & the Gateway API (Envoy)"},h="Exposing Services with Ingress & the Gateway API (Envoy)",l={},d=[{value:"The analogy: the reception desk of an office building",id:"the-analogy-the-reception-desk-of-an-office-building",level:2},{value:"Service versus Ingress: two different jobs",id:"service-versus-ingress-two-different-jobs",level:2},{value:"An Ingress object is only a rule set",id:"an-ingress-object-is-only-a-rule-set",level:2},{value:"How outside traffic actually reaches Envoy",id:"how-outside-traffic-actually-reaches-envoy",level:2},{value:"When to use a Service, and when to use an Ingress",id:"when-to-use-a-service-and-when-to-use-an-ingress",level:2},{value:"Name-based virtual hosting versus path-based routing",id:"name-based-virtual-hosting-versus-path-based-routing",level:2},{value:"The Gateway API: the same job, split across roles",id:"the-gateway-api-the-same-job-split-across-roles",level:2},{value:"Where this leaves the app",id:"where-this-leaves-the-app",level:2}];function c(e){let n={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"exposing-services-with-ingress--the-gateway-api-envoy",children:"Exposing Services with Ingress & the Gateway API (Envoy)"})}),"\n",(0,o.jsx)(a.A,{src:"decks/m7-envoy-ingress.html",title:"M7 \u2014 Exposing Services with Ingress & the Gateway API (Envoy)"}),"\n",(0,o.jsxs)(n.p,{children:["By now the Fernwood Goods app runs fully on the cluster. You have a frontend Deployment, a backend\nDeployment, and a Postgres StatefulSet, all wired together by Services. Inside the cluster, everything\ncan reach everything else by name. But step outside the cluster and the app is out of reach. A Service\ngives you a stable address, but only ",(0,o.jsx)(n.em,{children:"for callers that are already inside the cluster"}),". It does nothing to\nlet a browser on someone's laptop reach the storefront."]}),"\n",(0,o.jsxs)(n.p,{children:["In M4 you worked around this with a ",(0,o.jsx)(n.strong,{children:"NodePort"}),". You gave the frontend Service a high port on every node\nand hit it directly. That is fine for a demo, but it breaks down in production. A NodePort gives you one\nnumeric port per Service (",(0,o.jsx)(n.code,{children:"30080"}),", ",(0,o.jsx)(n.code,{children:"31711"}),", and so on). No hostnames, no paths, no TLS (that is, no HTTPS\nencryption), and no single place to apply one rule to all incoming traffic. Real traffic arrives as\n",(0,o.jsx)(n.code,{children:"https://shop.example.com/"})," and ",(0,o.jsx)(n.code,{children:"https://api.example.com/orders"}),", on port 443, sorted by hostname and\npath. Nothing you have built so far can do that sorting. This module adds the layer that can: an\n",(0,o.jsx)(n.strong,{children:"Ingress"}),", run by ",(0,o.jsx)(n.strong,{children:"Envoy"}),"."]}),"\n",(0,o.jsx)(n.h2,{id:"the-analogy-the-reception-desk-of-an-office-building",children:"The analogy: the reception desk of an office building"}),"\n",(0,o.jsx)(n.p,{children:"Imagine a large office building with many companies inside it. Every company has its own internal phone\nswitchboard. That switchboard is the Service you built in M4. Dial it and you reach whoever is on duty in\nthat company, and you neither know nor care which desk they sit at. That part is already solved."}),"\n",(0,o.jsxs)(n.p,{children:["But a visitor coming from the street does not walk straight to a switchboard. They come through ",(0,o.jsx)(n.strong,{children:"one main\nentrance"})," into a ",(0,o.jsx)(n.strong,{children:"single lobby"}),", and they meet a ",(0,o.jsx)(n.strong,{children:"receptionist"}),'. The receptionist reads who the\nvisitor wants to see. Maybe "I\'m here for Fernwood Sales", or "deliveries go to the loading dock". Then\nthey send the visitor to the right floor and the right internal number. One street address, one lobby, one\ndesk that reads the request and passes it on.']}),"\n",(0,o.jsxs)(n.p,{children:["That receptionist is the ",(0,o.jsx)(n.strong,{children:"Ingress"}),". The building's single street entrance is the one entry point all\noutside traffic comes through. The receptionist reads each arriving HTTP request, that is, its\n",(0,o.jsx)(n.strong,{children:"hostname"})," (like ",(0,o.jsx)(n.code,{children:"shop.fernwood.local"}),") and its ",(0,o.jsx)(n.strong,{children:"URL path"})," (like ",(0,o.jsx)(n.code,{children:"/api"}),"), and forwards it to the\ncorrect Service. That Service then does its own internal switchboard job. You are not replacing the\nswitchboards. You are putting a receptionist in front of them, so the outside world gets one door and one\nset of directions instead of a wall of numbered side entrances."]}),"\n",(0,o.jsx)(n.h2,{id:"service-versus-ingress-two-different-jobs",children:"Service versus Ingress: two different jobs"}),"\n",(0,o.jsx)(n.p,{children:'It is easy to mix these two up, because both of them "route traffic". But they work at different layers\nand solve different problems.'}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"Service"})," works at layer 4, which is the TCP/UDP level. It spreads a connection across a set of Pods\nby IP and port. It does not read the HTTP request at all. It cannot tell ",(0,o.jsx)(n.code,{children:"GET /products"})," from\n",(0,o.jsx)(n.code,{children:"GET /health"}),", and it has no idea which hostname the client asked for. That information sits up in the HTTP\nrequest, and the Service never looks inside it."]}),"\n",(0,o.jsxs)(n.p,{children:["An ",(0,o.jsx)(n.strong,{children:"Ingress"})," works at layer 7, which is the HTTP level. It reads the request line and the headers. That\nis what lets it route on ",(0,o.jsx)(n.strong,{children:"hostname"})," (",(0,o.jsx)(n.code,{children:"shop.fernwood.local"})," versus ",(0,o.jsx)(n.code,{children:"api.fernwood.local"}),") and on ",(0,o.jsx)(n.strong,{children:"path"}),"\n(",(0,o.jsx)(n.code,{children:"/"})," versus ",(0,o.jsx)(n.code,{children:"/api"}),"), handle TLS, and put many Services behind one external address. It sits ",(0,o.jsx)(n.em,{children:"in front of"}),"\nthe Services and hands each request to one of them."]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  U[Browser<br/>outside the cluster] --\x3e|HTTP host + path| E[Ingress / Envoy<br/>L7 front door]\n  subgraph cluster [Kubernetes cluster]\n    E --\x3e|host: fernwood.local| FS[frontend Service<br/>L4 switchboard]\n    E --\x3e|host: api.fernwood.local| BS[backend Service<br/>L4 switchboard]\n    FS --\x3e FP[frontend Pods]\n    BS --\x3e BP[backend Pods]\n  end"}),"\n",(0,o.jsx)(n.p,{children:"The Ingress does not replace the Service. It feeds it. The request still lands on a Service, which still\ndoes the layer 4 load-balancing across healthy Pods you saw in M4. The Ingress just adds the layer 7\nsorting on top."}),"\n",(0,o.jsx)(n.h2,{id:"an-ingress-object-is-only-a-rule-set",children:"An Ingress object is only a rule set"}),"\n",(0,o.jsxs)(n.p,{children:["Now here is the part that trips people up. When you ",(0,o.jsx)(n.code,{children:"kubectl apply"})," an Ingress, ",(0,o.jsx)(n.strong,{children:"nothing routes yet"}),". An\nIngress object is only a ",(0,o.jsx)(n.em,{children:"rule set"}),'. Think of it as a piece of paper that says "requests for this hostname\ngo to that Service". It has no process behind it, no listening socket, and no traffic.']}),"\n",(0,o.jsxs)(n.p,{children:["Something has to ",(0,o.jsx)(n.strong,{children:"read"})," those rules and actually carry them out: open a real port, accept connections,\nread each request, and forward it. That something is the ",(0,o.jsx)(n.strong,{children:"Ingress controller"}),". The controller's whole\njob is to watch Ingress objects and set up a real proxy to match. Without a controller running, an Ingress\nobject just sits there and does nothing. You can create as many as you like and no packet will move."]}),"\n",(0,o.jsxs)(n.p,{children:["Back to the building. The Ingress object is the ",(0,o.jsx)(n.strong,{children:"printed directory"}),' posted at reception ("Fernwood\nSales, 4th floor"). The controller is the ',(0,o.jsx)(n.strong,{children:"receptionist"})," who actually reads that directory and walks\nvisitors to the lift. A directory with no one at the desk routes nobody."]}),"\n",(0,o.jsxs)(n.p,{children:["Kubernetes ships the Ingress ",(0,o.jsx)(n.em,{children:"object"})," type in the core API, but on purpose it ships ",(0,o.jsx)(n.strong,{children:"no controller"}),". You\nchoose and install one yourself. The common teaching default is the NGINX ingress controller. Fernwood's\nplatform team runs ",(0,o.jsx)(n.strong,{children:"Envoy"})," instead. Envoy is a fast layer 7 proxy, and it is the data plane (the part\nthat actually moves the traffic) behind most modern service meshes and API gateways. Raw Envoy on its own\ndoes not understand Kubernetes Ingress objects. So you run an Envoy-based controller that does the watching\nand the setting-up for it. In this course that controller is ",(0,o.jsx)(n.strong,{children:"Contour"}),", a CNCF project that uses Envoy\nas its data plane. Usefully, Contour speaks both the classic Ingress API and the newer Gateway API from a\nsingle install."]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  subgraph plane [Control plane]\n    I[Ingress object<br/>rule set only] --\x3e|watched by| C[Contour<br/>Ingress controller]\n  end\n  C --\x3e|programs via xDS| X[Envoy<br/>data plane, real port 80/443]\n  U[Outside traffic] --\x3e X\n  X --\x3e S[Services then Pods]"}),"\n",(0,o.jsxs)(n.p,{children:["Two boxes, two jobs. ",(0,o.jsx)(n.strong,{children:"Contour"})," is the brain that reads Kubernetes objects and works out the config.\n",(0,o.jsx)(n.strong,{children:"Envoy"})," is the muscle that holds the open port and moves the bytes. Every Ingress and route you write\nbecomes Envoy configuration that Contour pushes down to it."]}),"\n",(0,o.jsx)(n.h2,{id:"how-outside-traffic-actually-reaches-envoy",children:"How outside traffic actually reaches Envoy"}),"\n",(0,o.jsxs)(n.p,{children:["The controller sets up Envoy, but something still has to get a packet from the outside world ",(0,o.jsx)(n.em,{children:"to"})," Envoy in\nthe first place. The Envoy Pods are exposed by a Service of their own, and this is where the layers stack\nup nicely. On a cloud provider, that Service is of type ",(0,o.jsx)(n.strong,{children:"LoadBalancer"}),". The cloud creates a real\nexternal load balancer with a public IP, and every request to that IP lands on Envoy. That is the normal\nproduction entry point: one address for the whole cluster, in front of the one Envoy, in front of every app\nService."]}),"\n",(0,o.jsxs)(n.p,{children:["Your KIND cluster has no cloud behind it, so that LoadBalancer Service never gets an external IP. It stays\n",(0,o.jsx)(n.code,{children:"<pending>"})," forever. That is expected, not a fault. To reach Envoy from your laptop, you use\n",(0,o.jsx)(n.code,{children:"kubectl port-forward"})," against the Envoy Service, which opens a local port straight to it. The routing you\nare testing is the same either way. Only the last hop, from your machine to Envoy, is different. Keep this\npicture in mind: ",(0,o.jsx)(n.strong,{children:"LoadBalancer or NodePort gets you to Envoy; the Ingress rules decide where Envoy sends\nyou next."})]}),"\n",(0,o.jsx)(n.h2,{id:"when-to-use-a-service-and-when-to-use-an-ingress",children:"When to use a Service, and when to use an Ingress"}),"\n",(0,o.jsxs)(n.p,{children:["A Service of type LoadBalancer can expose a single app to the outside world on its own, with no Ingress\nneeded. So when do you add one? Use a plain LoadBalancer Service when you have ",(0,o.jsx)(n.em,{children:"one"})," thing to expose and it\nis not HTTP, or when you really want a separate external address for each app. Reach for an ",(0,o.jsx)(n.strong,{children:"Ingress"})," the\nmoment you have ",(0,o.jsx)(n.em,{children:"several"})," HTTP Services to expose and want them behind ",(0,o.jsx)(n.strong,{children:"one"})," address, sorted by hostname\nand path, with TLS handled in one place. One external IP, one certificate store, many apps. Bringing\neverything together like this is the reason Ingress exists. The cost is the other half of the argument. A\nLoadBalancer per Service means a real, billed cloud load balancer for each one. One shared ingress is\ncheaper and easier to reason about than a dozen public IPs."]}),"\n",(0,o.jsx)(n.h2,{id:"name-based-virtual-hosting-versus-path-based-routing",children:"Name-based virtual hosting versus path-based routing"}),"\n",(0,o.jsx)(n.p,{children:"An Ingress sorts traffic in two ways, and it helps to be clear about which is which, because you will use\nthem in different situations."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Name-based virtual hosting"})," routes on the ",(0,o.jsx)(n.strong,{children:"hostname"})," in the request. Many hostnames, one entry point,\nand each hostname sent to a different Service:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.code,{children:"fernwood.local"})," \u2192 the frontend Service"]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.code,{children:"api.fernwood.local"})," \u2192 the backend Service"]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"This is what you want when the parts of your system are really separate properties, like a marketing site,\nan app, and an API, that happen to share one ingress. Each one gets its own clean hostname and its own\ncertificate, and they do not clash."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Path-based routing"})," keeps ",(0,o.jsx)(n.strong,{children:"one hostname"})," and routes on the ",(0,o.jsx)(n.strong,{children:"URL path"}),":"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.code,{children:"shop.fernwood.local/"})," \u2192 the frontend Service"]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.code,{children:"shop.fernwood.local/api"})," \u2192 the backend Service"]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["This is what you want when it is really one property that a user thinks of as a single site, but different\npath prefixes are served by different backends. The user sees one domain. Behind it, ",(0,o.jsx)(n.code,{children:"/api"})," is a separate\nService from ",(0,o.jsx)(n.code,{children:"/"}),". When two rules could both match, the ",(0,o.jsx)(n.strong,{children:"more specific (longer) prefix wins"}),", so ",(0,o.jsx)(n.code,{children:"/api"})," is\npicked over the catch-all ",(0,o.jsx)(n.code,{children:"/"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["You can mix both, and in a real system you usually do. The main idea stays simple: the receptionist can\nsort visitors by ",(0,o.jsx)(n.em,{children:"which company they name"})," (the host) or by ",(0,o.jsx)(n.em,{children:"which department they ask for"})," (the path), and\noften by both."]}),"\n",(0,o.jsx)(n.h2,{id:"the-gateway-api-the-same-job-split-across-roles",children:"The Gateway API: the same job, split across roles"}),"\n",(0,o.jsxs)(n.p,{children:["Ingress has a design flaw that only shows up at organisational scale. It is a ",(0,o.jsx)(n.strong,{children:"single flat object"})," that\ncrams three different concerns into one YAML that one team must own: which controller runs it, what the\nentry point looks like, and the actual routing rules. In a cluster shared by a platform team and several\napp teams, that is a fight waiting to happen. The app team wants to change a route, but the object they\nmust edit also holds infrastructure settings they should not touch."]}),"\n",(0,o.jsxs)(n.p,{children:["The ",(0,o.jsx)(n.strong,{children:"Gateway API"})," is the newer and more flexible successor. Its main move is to ",(0,o.jsx)(n.strong,{children:"split that one object\ninto three"}),", and each part is owned by the team that should own it:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"GatewayClass"})," names ",(0,o.jsx)(n.em,{children:"which implementation"})," backs this (here, Contour and Envoy). It is cluster-scoped.\nThe platform team registers it once, the way M6's StorageClass named a provisioner once."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Gateway"})," is the actual ",(0,o.jsx)(n.strong,{children:"listener, or entry point"}),": this port, this protocol, this address. The infra\nteam owns this shared front door."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"HTTPRoute"})," holds the ",(0,o.jsx)(n.strong,{children:"routing rules"}),": this hostname and path go to that Service. App teams own these\nand ",(0,o.jsx)(n.em,{children:"attach"})," them to the Gateway without ever touching it."]}),"\n"]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart TD\n  subgraph platform [Platform team owns]\n    GC[GatewayClass<br/>= Contour/Envoy]\n  end\n  subgraph infra [Infra team owns]\n    GW[Gateway<br/>listener :80]\n  end\n  subgraph appteam [App teams own]\n    R1[HTTPRoute<br/>store.fernwood.local to frontend]\n    R2[HTTPRoute<br/>store-api.fernwood.local to backend]\n  end\n  GC --\x3e GW\n  R1 --\x3e|attaches to| GW\n  R2 --\x3e|attaches to| GW"}),"\n",(0,o.jsxs)(n.p,{children:["That separation is the whole point. The infra team defines the Gateway once and never has to open it\nagain. Each app team ships HTTPRoutes for its own hostnames and paths, on its own schedule, with permission\nto touch only its own routes. The same routing you can write with a classic Ingress, you can also write\nwith a Gateway plus HTTPRoutes. Same result, cleaner ownership. Contour serves both APIs on the ",(0,o.jsx)(n.strong,{children:"same\nEnvoy"})," at once, and that is exactly what the lab shows: the classic Ingress rules and the Gateway API\nroutes running side by side through one data plane."]}),"\n",(0,o.jsx)(n.p,{children:"You will use classic Ingress for a long time yet. It is everywhere, and for a single team it is perfectly\nfine. Reach for the Gateway API when more than one team shares the front door, or when you need routing\nthat Ingress cannot express cleanly. Knowing both, and knowing that they both compile down to the same\nEnvoy config, is what lets you read any cluster someone hands you."}),"\n",(0,o.jsx)(n.h2,{id:"where-this-leaves-the-app",children:"Where this leaves the app"}),"\n",(0,o.jsxs)(n.p,{children:["At the end of this module, Fernwood has a real front door. Outside traffic arrives at one entry point,\nEnvoy reads the hostname and path, and routes it to the frontend, the backend, or (as the case study\nshows) a completely unrelated Spring Boot service, all through the same controller. The next module locks\nthat door down. ",(0,o.jsx)(n.strong,{children:"NetworkPolicy"})," decides which traffic is even allowed to move, and the ingress path you\nbuilt here is one of the flows M8 has to keep open on purpose."]})]})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},7684(e,n,t){t.d(n,{A:()=>r});var s=t(4848);t(6540);var o=t(6497);function r({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,s.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>i});var s=t(6540);let o={},r=s.createContext(o);function a(e){let n=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);